static const uint16_t *font_cn_find(uint32_t codepoint) {
    for(uint32_t i=0;i<sizeof(font_cn_glyphs)/sizeof(font_cn_glyphs[0]);++i)
        if(font_cn_glyphs[i].codepoint==codepoint) return font_cn_glyphs[i].rows;
    return 0;
}
